const EMBEDDED_ALPHA_MAP_LENGTHS = {
  48: 2304,
  96: 9216,
  "96-20260520": 9216,
  "48c": 2304
};

const EMBEDDED_ALPHA_MAP_BASE64 = {
  48: "",
  96: "",
  "96-20260520": "",
  "48c": ""
};

const _decodedCache = new Map();

function _decodeBase64(str) {
  const binary = atob(str);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

/**
 * Decode and return an alpha map Float32Array for the given key.
 * Results are cached; returns a fresh copy each call to prevent mutation.
 * @param {string|number} key  Alpha map key (e.g. "96", "48", "96-20260520", "48c")
 * @returns {Float32Array|null}
 */
function getAlphaMap(key) {
  const k = String(key);
  if (!(k in EMBEDDED_ALPHA_MAP_BASE64)) return null;
  if (!_decodedCache.has(k)) {
    const bytes = _decodeBase64(EMBEDDED_ALPHA_MAP_BASE64[k]);
    const floats = new Float32Array(bytes.buffer, bytes.byteOffset, EMBEDDED_ALPHA_MAP_LENGTHS[k]);
    _decodedCache.set(k, new Float32Array(floats));
  }
  return new Float32Array(_decodedCache.get(k));
}


// Expose globally for the image engine
if (typeof globalThis !== 'undefined') {
  globalThis.OneShotSEO_getAlphaMap = getAlphaMap;
}

(function () {
  'use strict';

  // Dead-zone: pixels with alpha below this are completely skipped.
  // This prevents shadow artifacts from near-zero noise in the alpha map.
  const DEAD_ZONE = 3 / 255;

  // The Gemini sparkle watermark is a pure white overlay (RGB 255,255,255)
  const OVERLAY_COLOR = 255;

  // Detection configurations  -- matches Gemini's known watermark placements
  const VARIANTS = [
    { logoSize: 96, marginRight: 64, marginBottom: 64, alphaKey: '96', label: '96px · 64px margin' },
    { logoSize: 96, marginRight: 192, marginBottom: 192, alphaKey: '96-20260520', label: '96px · 192px margin' },
    { logoSize: 48, marginRight: 96, marginBottom: 96, alphaKey: '48', label: '48px · 96px margin' },
    { logoSize: 48, marginRight: 32, marginBottom: 32, alphaKey: '48c', label: '48px · 32px margin' }
  ];

  // Alpha map cache
  const alphaCache = new Map();

  /**
   * Retrieve the decoded alpha map for a given key.
   * @param {string} key
   * @returns {Float32Array}
   */
  function getAlpha(key) {
    if (alphaCache.has(key)) return alphaCache.get(key);
    if (typeof globalThis.OneShotSEO_getAlphaMap !== 'function') return null;
    const data = globalThis.OneShotSEO_getAlphaMap(key);
    if (!data) return null;
    alphaCache.set(key, data);
    return data;
  }

  /**
   * Compute the expected watermark region position (bottom-right anchor).
   */
  function getRegion(imgW, imgH, variant) {
    return {
      x: imgW - variant.marginRight - variant.logoSize,
      y: imgH - variant.marginBottom - variant.logoSize,
      size: variant.logoSize
    };
  }

  /**
   * Check if a region fits entirely within the image bounds.
   */
  function regionInBounds(imgW, imgH, region) {
    return region.x >= 0 && region.y >= 0 &&
      region.x + region.size <= imgW &&
      region.y + region.size <= imgH;
  }

  function computeNCC(data, imgW, region, alpha, size) {
    const n = size * size;
    let sumA = 0, sumI = 0;
    const imgLum = new Float32Array(n);

    for (let r = 0; r < size; r++) {
      const rowOff = 4 * ((region.y + r) * imgW + region.x);
      for (let c = 0; c < size; c++) {
        const px = rowOff + 4 * c;
        const lum = 0.299 * data[px] + 0.587 * data[px + 1] + 0.114 * data[px + 2];
        imgLum[r * size + c] = lum;
        sumI += lum;
        sumA += alpha[r * size + c];
      }
    }

    const meanA = sumA / n;
    const meanI = sumI / n;

    let cov = 0, varA = 0, varI = 0;
    for (let i = 0; i < n; i++) {
      const dA = alpha[i] - meanA;
      const dI = imgLum[i] - meanI;
      cov += dA * dI;
      varA += dA * dA;
      varI += dI * dI;
    }

    const denom = Math.sqrt(varA * varI);
    return denom > 1e-6 ? cov / denom : 0;
  }

  function detect(imageData) {
    const { width: W, height: H, data } = imageData;
    let best = null;

    for (const variant of VARIANTS) {
      const baseRegion = getRegion(W, H, variant);
      if (!regionInBounds(W, H, baseRegion)) continue;

      const alpha = getAlpha(variant.alphaKey);
      if (!alpha) continue;

      // Search with ±3px jitter around expected position
      for (let dy = -3; dy <= 3; dy++) {
        for (let dx = -3; dx <= 3; dx++) {
          const region = {
            x: baseRegion.x + dx,
            y: baseRegion.y + dy,
            size: variant.logoSize
          };

          if (!regionInBounds(W, H, region)) continue;

          const ncc = computeNCC(data, W, region, alpha, variant.logoSize);

          if (!best || ncc > best.score) {
            best = {
              variant,
              region,
              alpha,
              score: ncc
            };
          }
        }
      }
    }

    return best;
  }

  /**
   * Compute residual correlation for a given gain factor.
   * Used by bisection gain calibration.
   */
  function residualCorrelation(lumChannel, alpha, size, gain) {
    const n = size * size;
    let sumW = 0, sumC = 0;
    const corrected = new Float32Array(n);

    for (let i = 0; i < n; i++) {
      const ai = alpha[i];
      const effAlpha = Math.max(0, ai - DEAD_ZONE) * gain;

      let c = lumChannel[i];
      if (effAlpha >= 0.002) {
        const a = Math.min(ai * gain, 0.99);
        c = (lumChannel[i] - a * OVERLAY_COLOR) / (1 - a);
        c = c < 0 ? 0 : c > 255 ? 255 : c;
      }

      corrected[i] = c;
      sumC += c;
      sumW += ai;
    }

    const meanW = sumW / n;
    const meanC = sumC / n;

    let num = 0, den = 0;
    for (let i = 0; i < n; i++) {
      const dW = alpha[i] - meanW;
      num += dW * (corrected[i] - meanC);
      den += dW * dW;
    }

    return den > 1e-6 ? num / den : 0;
  }

  /**
   * Calibrate the removal gain via bisection.
   */
  function calibrateGain(imgData, imgW, region, alpha) {
    const size = region.size;

    // Extract luminance channel for the region
    const lum = new Float32Array(size * size);
    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        const px = 4 * ((region.y + r) * imgW + region.x + c);
        lum[r * size + c] = 0.299 * imgData[px] + 0.587 * imgData[px + 1] + 0.114 * imgData[px + 2];
      }
    }

    // Bisection bounds
    let lo = 0.55;
    let hi = 1.18;

    // Check if bisection endpoints have proper sign difference
    if (residualCorrelation(lum, alpha, size, lo) <= 0) return lo;
    if (residualCorrelation(lum, alpha, size, hi) > 0) return hi;

    // Bisect to find the zero-crossing
    for (let iter = 0; iter < 12; iter++) {
      const mid = (lo + hi) / 2;
      if (residualCorrelation(lum, alpha, size, mid) > 0) {
        lo = mid;
      } else {
        hi = mid;
      }
    }

    return (lo + hi) / 2;
  }

  /**
   * Apply reverse alpha compositing to remove the watermark.
   */
  function reverseBlend(imageData, region, alpha, gain) {
    const { width: W, data } = imageData;
    const size = region.size;
    const effectiveGain = gain > 0 ? gain : 1;

    for (let r = 0; r < size; r++) {
      const rowOff = 4 * ((region.y + r) * W + region.x);
      for (let c = 0; c < size; c++) {
        const ai = alpha[r * size + c];

        // Dead-zone: skip pixels with negligible watermark contribution
        if (Math.max(0, ai - DEAD_ZONE) * effectiveGain < 0.002) continue;

        const a = Math.min(ai * effectiveGain, 0.99);
        const inv = 1 - a;
        const px = rowOff + 4 * c;

        for (let ch = 0; ch < 3; ch++) {
          const orig = (data[px + ch] - a * OVERLAY_COLOR) / inv;
          data[px + ch] = orig < 0 ? 0 : orig > 255 ? 255 : Math.round(orig);
        }
      }
    }
  }

  /**
   * Compute Laplacian-brightness correlation to decide if inpainting is needed.
   */
  function laplacianCorrelation(imageData, alpha, region) {
    const { width: W, data } = imageData;
    const size = region.size;
    const n = size * size;

    const lap = new Float32Array(n);
    const getAlphaVal = (r, c) => (r < 0 || r >= size || c < 0 || c >= size) ? 0 : alpha[r * size + c];

    let lapSum = 0;
    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        const val = getAlphaVal(r - 1, c) + getAlphaVal(r + 1, c) + getAlphaVal(r, c - 1) + getAlphaVal(r, c + 1) - 4 * getAlphaVal(r, c);
        lap[r * size + c] = val;
        lapSum += val;
      }
    }
    const lapMean = lapSum / n;

    const bright = new Float32Array(n);
    let brightSum = 0;
    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        const px = 4 * ((region.y + r) * W + region.x + c);
        const lum = 0.299 * data[px] + 0.587 * data[px + 1] + 0.114 * data[px + 2];
        bright[r * size + c] = lum;
        brightSum += lum;
      }
    }
    const brightMean = brightSum / n;

    let num = 0, den = 0;
    for (let i = 0; i < n; i++) {
      const dL = lap[i] - lapMean;
      num += dL * (bright[i] - brightMean);
      den += dL * dL;
    }

    return den > 1e-6 ? Math.abs(num / den) : 0;
  }

  /**
   * Exemplar-based inpainting.
   */
  function inpaint(imageData, alpha, region) {
    const { width: W, height: H, data } = imageData;
    const size = region.size;

    const pad = 30;
    const workX = Math.max(0, region.x - pad);
    const workY = Math.max(0, region.y - pad);
    const workW = Math.min(W - workX, size + 2 * pad);
    const workH = Math.min(H - workY, size + 2 * pad);
    const workN = workW * workH;

    const imgIdx = (flatIdx, ch) => 4 * ((workY + Math.floor(flatIdx / workW)) * W + workX + (flatIdx % workW)) + ch;
    const getLum = (flatIdx) => 0.299 * data[imgIdx(flatIdx, 0)] + 0.587 * data[imgIdx(flatIdx, 1)] + 0.114 * data[imgIdx(flatIdx, 2)];

    const mask = new Uint8Array(workN);
    let hasDamage = false;

    for (let r = 0; r < workH; r++) {
      for (let c = 0; c < workW; c++) {
        const alphaR = workY + r - region.y;
        const alphaC = workX + c - region.x;
        if (alphaR >= 0 && alphaR < size && alphaC >= 0 && alphaC < size) {
          if (alpha[alphaR * size + alphaC] > 0.04) {
            mask[r * workW + c] = 1;
            hasDamage = true;
          }
        }
      }
    }

    if (!hasDamage) return false;

    // Dilate mask by 2px
    for (let d = 0; d < 2; d++) {
      const copy = mask.slice();
      for (let r = 0; r < workH; r++) {
        for (let c = 0; c < workW; c++) {
          if (mask[r * workW + c]) {
            if (r > 0) copy[(r - 1) * workW + c] = 1;
            if (r < workH - 1) copy[(r + 1) * workW + c] = 1;
            if (c > 0) copy[r * workW + c - 1] = 1;
            if (c < workW - 1) copy[r * workW + c + 1] = 1;
          }
        }
      }
      mask.set(copy);
    }

    const known = new Uint8Array(workN);
    const confidence = new Float32Array(workN);
    for (let i = 0; i < workN; i++) {
      known[i] = mask[i] ? 0 : 1;
      confidence[i] = mask[i] ? 0 : 1;
    }

    const patchR = 3;
    const refPatches = [];
    for (let r = patchR; r < workH - patchR; r += 2) {
      for (let c = patchR; c < workW - patchR; c += 2) {
        let allClean = true;
        for (let dr = -patchR; dr <= patchR && allClean; dr++) {
          for (let dc = -patchR; dc <= patchR; dc++) {
            if (mask[(r + dr) * workW + (c + dc)]) {
              allClean = false;
              break;
            }
          }
        }
        if (allClean) refPatches.push(r * workW + c);
      }
    }

    if (!refPatches.length) return false;

    let remaining = 0;
    for (let i = 0; i < workN; i++) {
      if (!known[i]) remaining++;
    }

    let maxIter = 3 * workN;
    while (remaining > 0 && maxIter-- > 0) {
      let bestIdx = -1, bestPriority = -1;

      for (let r = 0; r < workH; r++) {
        for (let c = 0; c < workW; c++) {
          const idx = r * workW + c;
          if (known[idx]) continue;

          const hasKnownNeighbor = (
            (r > 0 && known[idx - workW]) ||
            (r < workH - 1 && known[idx + workW]) ||
            (c > 0 && known[idx - 1]) ||
            (c < workW - 1 && known[idx + 1])
          );
          if (!hasKnownNeighbor) continue;

          let confSum = 0, confCount = 0;
          for (let dr = -patchR; dr <= patchR; dr++) {
            for (let dc = -patchR; dc <= patchR; dc++) {
              const nr = r + dr, nc = c + dc;
              if (nr < 0 || nr >= workH || nc < 0 || nc >= workW) continue;
              confSum += confidence[nr * workW + nc];
              confCount++;
            }
          }
          const avgConf = confSum / confCount;

          let gradX = 0, gradY = 0;
          if (c > 0 && c < workW - 1 && known[idx - 1] && known[idx + 1]) {
            gradX = getLum(idx + 1) - getLum(idx - 1);
          }
          if (r > 0 && r < workH - 1 && known[idx - workW] && known[idx + workW]) {
            gradY = getLum(idx + workW) - getLum(idx - workW);
          }

          const priority = avgConf * (0.02 + Math.sqrt(gradX * gradX + gradY * gradY) / 255);

          if (priority > bestPriority) {
            bestPriority = priority;
            bestIdx = idx;
          }
        }
      }

      if (bestIdx < 0) break;

      const targetR = Math.floor(bestIdx / workW);
      const targetC = bestIdx % workW;

      let bestPatchIdx = -1, bestDist = Infinity;
      for (const refIdx of refPatches) {
        const refR = Math.floor(refIdx / workW);
        const refC = refIdx % workW;

        let dist = 0, count = 0;
        for (let dr = -patchR; dr <= patchR; dr++) {
          for (let dc = -patchR; dc <= patchR; dc++) {
            const tr = targetR + dr, tc = targetC + dc;
            if (tr < 0 || tr >= workH || tc < 0 || tc >= workW) continue;
            const tidx = tr * workW + tc;
            if (!known[tidx]) continue;

            const ridx = (refR + dr) * workW + (refC + dc);
            for (let ch = 0; ch < 3; ch++) {
              const diff = data[imgIdx(tidx, ch)] - data[imgIdx(ridx, ch)];
              dist += diff * diff;
            }
            count++;
          }
        }
        if (count !== 0) {
          dist /= count;
          if (dist < bestDist) {
            bestDist = dist;
            bestPatchIdx = refIdx;
          }
        }
      }

      if (bestPatchIdx < 0) break;

      const srcR = Math.floor(bestPatchIdx / workW);
      const srcC = bestPatchIdx % workW;

      for (let dr = -patchR; dr <= patchR; dr++) {
        for (let dc = -patchR; dc <= patchR; dc++) {
          const tr = targetR + dr, tc = targetC + dc;
          if (tr < 0 || tr >= workH || tc < 0 || tc >= workW) continue;
          const tidx = tr * workW + tc;
          if (known[tidx]) continue;

          const sidx = (srcR + dr) * workW + (srcC + dc);
          for (let ch = 0; ch < 3; ch++) {
            data[imgIdx(tidx, ch)] = data[imgIdx(sidx, ch)];
          }
          known[tidx] = 1;
          confidence[tidx] = bestPriority;
          remaining--;
        }
      }
    }

    return true;
  }

  // =========================================================================
  //  PUBLIC API
  // =========================================================================

  /**
   * Process an ImageData to detect and remove the Gemini sparkle watermark.
   *
   * @param {ImageData} inputImageData  The source image (not mutated)
   * @param {object}    [opts]          Optional overrides
   * @param {boolean}   [opts.inpaint=true]  Enable exemplar-based inpainting
   * @param {number}    [opts.alphaGain]     Manual gain override (positive float)
   * @returns {{ imageData: ImageData, detection: object|null }}
   */
  function process(inputImageData, opts = {}) {
    // Work on a copy so the original is never mutated
    const imageData = new ImageData(
      new Uint8ClampedArray(inputImageData.data),
      inputImageData.width,
      inputImageData.height
    );

    // Check if alpha maps are available
    if (typeof globalThis.OneShotSEO_getAlphaMap !== 'function') {
      return { imageData, detection: null };
    }

    // Detection
    const hit = detect(imageData);

    if (!hit || hit.score < 0.2) {
      return { imageData, detection: null };
    }

    const { variant, region, alpha, score } = hit;

    // Gain calibration
    const autoGain = calibrateGain(imageData.data, imageData.width, region, alpha);
    const finalGain = autoGain * (Number.isFinite(opts.alphaGain) && opts.alphaGain > 0 ? opts.alphaGain : 1);

    // Reverse alpha compositing
    reverseBlend(imageData, region, alpha, finalGain);

    // Conditional inpainting
    let inpainted = false;
    if (opts.inpaint !== false) {
      const lapCorr = laplacianCorrelation(imageData, alpha, region);
      if (lapCorr > 1.2) {
        inpainted = inpaint(imageData, alpha, region);
      }
    }

    return {
      imageData,
      detection: {
        x: region.x,
        y: region.y,
        size: region.size,
        marginRight: variant.marginRight,
        marginBottom: variant.marginBottom,
        label: variant.label,
        alphaKey: variant.alphaKey,
        confidence: Math.max(0, score),
        autoGain,
        inpainted
      }
    };
  }

  // Expose globally
  globalThis.OneShotSEO_ImageEngine = { process };

})();

(function () {
  'use strict';

  document.addEventListener('DOMContentLoaded', () => {
    const config = window.OneShotSEO_ToolConfig || {};

    // ========= DOM References =========
    const dropZone = document.getElementById('drop-zone');
    const fileInput = document.getElementById('file-input');
    const uploadPrompt = document.getElementById('upload-prompt');
    const workspacePanel = document.getElementById('workspace-panel');
    const editorContainer = document.getElementById('editor-container');
    const canvas = document.getElementById('image-canvas');
    const ctx = canvas.getContext('2d');

    const errorAlert = document.getElementById('error-alert');
    const controlsSection = document.getElementById('controls-section');
    const processBtn = document.getElementById('process-btn');
    const downloadBtn = document.getElementById('download-btn');

    // Optional: result status badge (injected dynamically after processing)
    let resultBadge = document.getElementById('result-badge');

    // ========= State =========
    let originalImage = new Image();
    let originalImageSrc = '';
    let currentBlobUrl = null; // Track blob URL for cleanup

    // Accent color classes for drag highlight
    const accentBorderClass = config.accentColor === 'yellow'
      ? 'border-yellow-500'
      : 'border-primary-500';
    const accentBgClass = config.accentColor === 'yellow'
      ? 'bg-yellow-50/10'
      : 'bg-primary-50/10';

    // ========= File Upload / Drag-Drop =========
    dropZone.addEventListener('click', (e) => {
      // Prevent clicks on canvas or buttons from reopening file picker
      if (canvas && e.target === canvas) return;
      if (processBtn && (e.target === processBtn || processBtn.contains(e.target))) return;
      if (downloadBtn && (e.target === downloadBtn || downloadBtn.contains(e.target))) return;
      // Prevent clicks on dynamically-created buttons (Try New, etc.) from reopening file picker
      if (e.target.closest('#try-new-btn') || e.target.closest('#result-badge')) return;
      fileInput.click();
    });

    dropZone.addEventListener('dragover', (e) => {
      e.preventDefault();
      dropZone.classList.add(accentBorderClass, accentBgClass);
    });

    dropZone.addEventListener('dragleave', () => {
      dropZone.classList.remove(accentBorderClass, accentBgClass);
    });

    dropZone.addEventListener('drop', (e) => {
      e.preventDefault();
      dropZone.classList.remove(accentBorderClass, accentBgClass);
      if (e.dataTransfer.files && e.dataTransfer.files[0]) {
        handleImageFile(e.dataTransfer.files[0]);
      }
    });

    fileInput.addEventListener('change', (e) => {
      if (e.target.files && e.target.files[0]) {
        handleImageFile(e.target.files[0]);
      }
    });

    function handleImageFile(file) {
      if (!file.type.startsWith('image/')) {
        showError('Please upload a valid image file (PNG, JPG, WEBP).');
        return;
      }

      const reader = new FileReader();
      reader.onload = (event) => {
        originalImageSrc = event.target.result;
        originalImage = new Image();
        originalImage.onload = () => {
          setupPreview();
        };
        originalImage.src = originalImageSrc;
      };
      reader.readAsDataURL(file);
    }

    // ========= Preview Setup (Read-Only  -- No Drawing) =========
    const _dropZoneOriginalClasses = dropZone.className; // Save for reset

    function setupPreview() {
      hideError();

      // Gemini tool uses upload-prompt + editor-container inside drop-zone
      if (uploadPrompt) uploadPrompt.classList.add('hidden');
      if (editorContainer) {
        editorContainer.classList.remove('hidden');

        // Transform drop-zone from dashed upload area into a polished preview container
        dropZone.className = 'bg-slate-950 rounded-2xl overflow-hidden p-4 border border-slate-800 shadow-inner relative';
        dropZone.style.cursor = 'default';

        // Upgrade the inner canvas wrapper  -- no height cap so image shows at full proportions
        const canvasWrap = editorContainer.querySelector('div');
        if (canvasWrap) {
          canvasWrap.className = 'relative overflow-auto rounded-xl bg-slate-900 flex justify-center items-center';
        }
      }
      if (controlsSection) controlsSection.classList.remove('hidden');

      // Other tools use drop-zone + workspace-panel pattern (already styled well)
      if (workspacePanel) {
        dropZone.classList.add('hidden');
        workspacePanel.classList.remove('hidden');
      }

      downloadBtn.classList.add('hidden');
      hideResultBadge();

      // Setup canvas sizing and draw preview at original dimensions
      canvas.width = originalImage.naturalWidth;
      canvas.height = originalImage.naturalHeight;

      // Remove any CSS height caps so image displays at full original proportions
      canvas.style.maxHeight = 'none';
      canvas.style.width = '100%';
      canvas.style.height = 'auto';

      ctx.drawImage(originalImage, 0, 0);
    }

    // ========= Processing (Automatic Engine Detection) =========
    processBtn.addEventListener('click', () => {
      validateRecaptcha(() => {
        hideError();
        processBtn.disabled = true;
        const spinnerHTML = '<span class="animate-spin inline-block w-4 h-4 border-2 border-current border-t-transparent rounded-full mr-2"></span>';
        processBtn.innerHTML = spinnerHTML + ' Analyzing...';

        setTimeout(() => {
          try {
            runAutomaticRemoval();
          } catch (err) {
            showError('An error occurred during processing: ' + err.message);
            processBtn.disabled = false;
            processBtn.innerHTML = config.processLabel || 'Erase Watermark';
          }
        }, 100); // Small delay for UI to update spinner
      });
    });

    function runAutomaticRemoval() {
      // Redraw original clean image to get fresh pixel data
      ctx.drawImage(originalImage, 0, 0);
      const sourceData = ctx.getImageData(0, 0, canvas.width, canvas.height);

      // Call the professional engine (same as Chrome extension)
      if (typeof globalThis.OneShotSEO_ImageEngine === 'undefined') {
        showError('Image processing engine not loaded. Please refresh the page.');
        processBtn.disabled = false;
        processBtn.innerHTML = config.processLabel || 'Erase Watermark';
        return;
      }

      const result = globalThis.OneShotSEO_ImageEngine.process(sourceData);

      if (result.detection) {
        // Engine detected and cleaned the watermark  -- show result
        ctx.putImageData(result.imageData, 0, 0);

        // Show success state
        showResultBadge(true, result.detection);
        downloadBtn.classList.remove('hidden');
        setDownloadBlob();
      } else {
        // No watermark detected
        showResultBadge(false, null);
        // Still allow download of original
        downloadBtn.classList.remove('hidden');
        setDownloadBlob();
      }

      processBtn.disabled = false;
      processBtn.innerHTML = config.processLabel || 'Erase Watermark';
      processBtn.classList.add('hidden');

      // Add a subtle attention pulse to the download button
      downloadBtn.classList.add('animate-pulse');
      setTimeout(() => downloadBtn.classList.remove('animate-pulse'), 2000);

      showTryNewButton();
    }

    function setDownloadBlob() {
      // Revoke previous blob URL to free memory
      if (currentBlobUrl) {
        URL.revokeObjectURL(currentBlobUrl);
        currentBlobUrl = null;
      }

      canvas.toBlob(function (blob) {
        if (!blob) {
          // Fallback: if toBlob fails (very rare), use data URL as last resort
          downloadBtn.href = canvas.toDataURL('image/png');
          return;
        }
        currentBlobUrl = URL.createObjectURL(blob);
        downloadBtn.href = currentBlobUrl;
        downloadBtn.setAttribute('download', config.downloadName || 'cleaned-image.png');
      }, 'image/png');
    }

    // ========= Result Badge =========
    function showResultBadge(success, detection) {
      // Find or create badge container
      if (!resultBadge) {
        resultBadge = document.createElement('div');
        resultBadge.id = 'result-badge';
        const btnParent = processBtn.parentElement;
        if (btnParent) {
          btnParent.insertBefore(resultBadge, processBtn);
        }
      }

      if (success && detection) {
        resultBadge.className = 'p-3 rounded-xl text-sm font-medium flex items-center gap-2 bg-emerald-50 dark:bg-emerald-950/30 text-emerald-700 dark:text-emerald-400 border border-emerald-200 dark:border-emerald-800/50 mb-4';
        resultBadge.innerHTML = `
          <svg class="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"></path>
          </svg>
          <span><strong>Watermark removed successfully!</strong></span>`;
      } else {
        resultBadge.className = 'p-3 rounded-xl text-sm font-medium flex items-center gap-2 bg-amber-50 dark:bg-amber-950/30 text-amber-700 dark:text-amber-400 border border-amber-200 dark:border-amber-800/50 mb-4';
        resultBadge.innerHTML = `
          <svg class="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path>
          </svg>
          <span><strong>No Gemini watermark detected.</strong></span>`;
      }

      resultBadge.classList.remove('hidden');
    }

    function hideResultBadge() {
      if (resultBadge) {
        resultBadge.classList.add('hidden');
      }
    }

    // ========= Try New Image =========
    let tryNewBtn = null;

    function showTryNewButton() {
      if (!tryNewBtn) {
        tryNewBtn = document.createElement('button');
        tryNewBtn.id = 'try-new-btn';
        tryNewBtn.type = 'button';
        tryNewBtn.className = 'w-full sm:w-auto px-8 py-3.5 bg-slate-100 hover:bg-slate-200 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 font-bold rounded-xl transition-all transform hover:-translate-y-0.5 inline-flex items-center justify-center gap-2';
        tryNewBtn.innerHTML = `
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"></path>
          </svg>
          Try New Image`;
        tryNewBtn.addEventListener('click', (e) => {
          e.preventDefault();
          e.stopPropagation();
          resetToUpload();
        });

        const btnRow = downloadBtn.parentElement;
        if (btnRow) {
          btnRow.appendChild(tryNewBtn);
        }
      }
      tryNewBtn.classList.remove('hidden');
    }

    function hideTryNewButton() {
      if (tryNewBtn) tryNewBtn.classList.add('hidden');
    }

    function resetToUpload() {
      // Clear state
      originalImage = new Image();
      originalImageSrc = '';
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      fileInput.value = '';

      // Revoke blob URL to free memory
      if (currentBlobUrl) {
        URL.revokeObjectURL(currentBlobUrl);
        currentBlobUrl = null;
      }

      // Hide workspace, show upload prompt
      if (uploadPrompt) uploadPrompt.classList.remove('hidden');
      if (editorContainer) editorContainer.classList.add('hidden');
      if (controlsSection) controlsSection.classList.add('hidden');

      // Restore original drop-zone styling (dashed upload border)
      dropZone.className = _dropZoneOriginalClasses;
      dropZone.style.cursor = '';

      if (workspacePanel) {
        workspacePanel.classList.add('hidden');
        dropZone.classList.remove('hidden');
      }

      // Reset buttons and badges
      downloadBtn.classList.add('hidden');
      downloadBtn.href = '#';
      processBtn.disabled = false;
      processBtn.classList.remove('hidden');
      processBtn.innerHTML = config.processLabel || 'Erase Watermark';
      hideResultBadge();
      hideTryNewButton();
      hideError();
    }

    // ========= Error Display =========
    function showError(msg) {
      const errorTextSpan = document.getElementById('error-message-text');
      if (errorTextSpan) {
        errorTextSpan.textContent = msg;
      } else {
        errorAlert.textContent = msg;
      }
      errorAlert.classList.remove('hidden');
      errorAlert.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }

    function hideError() {
      errorAlert.classList.add('hidden');
    }
  });
})();

